import fitz
p = ".dsh-filess/session-74ad4119-8c6a-42b6-a38a-f25f30b6e44a/1d4abd1feec7-Nature Injectable ultrasonic sensor for wireless .pdf"
doc = fitz.open(p)
for pg in [2,4,5,6]:
    page = doc[pg-1]
    R = []
    for im in page.get_images(full=True):
        for r in page.get_image_rects(im[0]):
            R.append(fitz.Rect(r))
    ux0 = min(r.x0 for r in R); uy0 = min(r.y0 for r in R)
    ux1 = max(r.x1 for r in R); uy1 = max(r.y1 for r in R)
    cap_y = None
    d = page.get_text("dict")
    for blk in d["blocks"]:
        for line in blk.get("lines", []):
            for span in line.get("spans", []):
                t = span["text"]
                if f"Fig. {pg-1} |".replace("Fig.","Fig")  in t or (t.strip().startswith("Fig. ") and str(pg-1) in t):
                    pass
    # simpler textual scan
    dd = page.get_text("dict")
    for blk in dd["blocks"]:
        if blk["type"] != 0: continue
        for line in blk["lines"]:
            txt = "".join(s["text"] for s in line["spans"])
            if txt.strip().startswith(f"Fig. {pg-1}") or f"Fig. {pg-1} |" in txt or txt.strip()==f"Fig. {pg-1}":
                cap_y = line["bbox"][1]
                break
        if cap_y: break
    print(f"page {pg}: img_union=({ux0:.0f},{uy0:.0f})-({ux1:.0f},{uy1:.0f}) caption_y={cap_y}")
PY","description":"Compute image union bbox and caption y"}

